12	import java.math.BigDecimal;
13	import java.util.List;
14	import java.util.concurrent.CountDownLatch;
15	import java.util.concurrent.ExecutorService;
16	import java.util.concurrent.Executors;
17	import java.util.concurrent.Future;
18	import java.util.concurrent.TimeUnit;
19	import java.util.concurrent.atomic.AtomicInteger;
20	import org.junit.jupiter.api.DisplayName;
21	import org.junit.jupiter.api.Test;
22	import org.springframework.beans.factory.annotation.Autowired;
23	
24	/**
25	 * 真实并发 H2 测试：险情处置链下并发制定泄流方案，
26	 * 唯一索引保证同一尾矿库同时刻只有一个生效方案。
27	 */
28	class PlanConcurrencyIntegrationTest extends AbstractIntegrationTest {
29	
30	    @Autowired
31	    private PlanService planService;
32	    @Autowired
33	    private FlowSupport flow;
34	
35	    @Test
36	    @DisplayName("并发制定两个方案：恰一个生效，另一个被唯一约束拒绝，库内只有一个执行中方案")
37	    void concurrentPlansOnlyOneEffective() throws Exception {
38	        WarningView warning = flow.openWarning("w-concurrent-plan");
39	        RoutingView routing = flow.route("r-concurrent-plan", warning.warningNo(),
40	                new BigDecimal("200.0000"), new BigDecimal("400001"),
41	                new BigDecimal("150"), new BigDecimal("10"));
42	
43	        int threads = 8;
44	        ExecutorService pool = Executors.newFixedThreadPool(threads);
45	        CountDownLatch ready = new CountDownLatch(threads);
46	        CountDownLatch start = new CountDownLatch(1);
47	        AtomicInteger success = new AtomicInteger();
48	        AtomicInteger rejected = new AtomicInteger();
49	        java.util.List<Future<?>> futures = new java.util.ArrayList<>();
50	
51	        try {
52	            for (int i = 0; i < threads; i++) {
53	                final int idx = i;
54	                futures.add(pool.submit(() -> {
55	                    ready.countDown();
56	                    assertThat(start.await(5, TimeUnit.SECONDS)).isTrue();
57	                    List<OpeningItem> openings = List.of(new OpeningItem(
58	                            "并发孔口-" + idx, new BigDecimal("1.0"),
59	                            new BigDecimal("10.000")));
60	                    try {
61	                        PlanView view = planService.create(new PlanRequest(
62	                                "p-concurrent-" + idx, warning.warningNo(),
63	                                routing.routingNo(), openings));
64	                        if ("EFFECTIVE".equals(view.status())) {
65	                            success.incrementAndGet();
66	                        }
67	                    } catch (FloodControlException e) {
68	                        if ("PLAN_ALREADY_EFFECTIVE".equals(e.getCode())) {
69	                            rejected.incrementAndGet();
70	                        } else {
71	                            throw e;
72	                        }
73	                    }
74	                    return null;
75	                }));
76	            }
77	            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
78	            start.countDown();
79	            for (Future<?> f : futures) {
80	                f.get(30, TimeUnit.SECONDS);
81	            }
82	        } finally {
83	            pool.shutdownNow();
84	        }
85	
86	        assertThat(success.get()).isEqualTo(1);
87	        assertThat(rejected.get()).isEqualTo(threads - 1);
88	
89	        Integer effectiveCount = jdbcTemplate.queryForObject(
90	                "SELECT COUNT(1) FROM release_plan WHERE status = 'EFFECTIVE'", Integer.class);
91	        Integer totalCount = jdbcTemplate.queryForObject(
92	                "SELECT COUNT(1) FROM release_plan", Integer.class);
93	        Integer distinctActiveKey = jdbcTemplate.queryForObject(
94	                "SELECT COUNT(DISTINCT active_key) FROM release_plan WHERE active_key IS NOT NULL",
95	                Integer.class);
96	        assertThat(effectiveCount).isEqualTo(1);
97	        assertThat(totalCount).isEqualTo(1);
98	        assertThat(distinctActiveKey).isEqualTo(1);
99	    }
100	}
