12	import com.example.starter.flood.web.dto.WarningView;
13	import java.math.BigDecimal;
14	import java.util.List;
15	import org.junit.jupiter.api.DisplayName;
16	import org.junit.jupiter.api.Test;
17	import org.springframework.beans.factory.annotation.Autowired;
18	
19	/**
20	 * 泄流指令链 H2 集成测试：
21	 * 时限内签收、恰满 15 分钟超时升级、执行前置校验、回执偏差恰 10%/超阈原因必填、回执幂等。
22	 */
23	class OrderIntegrationTest extends AbstractIntegrationTest {
24	
25	    @Autowired
26	    private OrderService orderService;
27	    @Autowired
28	    private FlowSupport flow;
29	
30	    private PlanView issuedPlan() {
31	        WarningView warning = flow.openWarning("w-order-" + clock.instant().toEpochMilli());
32	        RoutingView routing = flow.route("r-order-" + clock.instant().toEpochMilli(),
33	                warning.warningNo(), new BigDecimal("200.0000"), new BigDecimal("400001"),
34	                new BigDecimal("150"), new BigDecimal("10"));
35	        return flow.createPlan("p-order-" + clock.instant().toEpochMilli(),
36	                warning.warningNo(), routing.routingNo(), FlowSupport.safeBoundaryOpenings());
37	    }
38	
39	    @Test
40	    @DisplayName("签收时限内正常签收→执行→回执闭环")
41	    void normalChain() {
42	        PlanView plan = issuedPlan();
43	        clock.advanceMinutes(14);
44	        OrderView signed = orderService.get(plan.orderNo());
45	        flow.sign(plan.orderNo(), "值班员甲");
46	        flow.execute(plan.orderNo(), "值班员甲");
47	        flow.receipt(plan.orderNo(), "rc-normal", "值班员甲",
48	                FlowSupport.safeBoundaryOpenings(), null);
49	        OrderView done = orderService.get(plan.orderNo());
50	        assertThat(done.status()).isEqualTo("RECEIPTED");
51	        assertThat(done.deviationRatio()).isEqualByComparingTo("0.000000");
52	        assertThat(signed.orderNo()).isEqualTo(plan.orderNo());
53	    }
54	
55	    @Test
56	    @DisplayName("恰满 15 分钟未签收：签收动作自动升级值班领导并留痕")
57	    void signExactlyAtDeadlineEscalates() {
58	        PlanView plan = issuedPlan();
59	        // 下达时刻 + 15 分钟（恰满，含边界）
60	        clock.advanceMinutes(15);
61	        flow.sign(plan.orderNo(), "值班员乙");
62	        OrderView view = orderService.get(plan.orderNo());
63	        assertThat(view.status()).isEqualTo("ESCALATED");
64	        assertThat(view.escalatedTo()).isEqualTo("值班领导");
65	        assertThat(view.escalatedAt()).isEqualTo(view.signDeadline());
66	        assertThat(view.signer()).isEqualTo("值班员乙");
67	        Integer eventCount = jdbcTemplate.queryForObject(
68	                "SELECT COUNT(1) FROM order_event WHERE order_id = "
69	                        + "(SELECT id FROM release_order WHERE order_no = ?) AND event_type = 'ESCALATED'",
70	                Integer.class, plan.orderNo());
71	        assertThat(eventCount).isEqualTo(1);
72	    }
73	
74	    @Test
75	    @DisplayName("超时巡检：恰满 15 分钟自动升级，未超时不升级；升级后仍可执行回执")
76	    void timeoutCheckBoundary() {
77	        PlanView plan = issuedPlan();
78	        clock.advanceMinutes(14);
79	        assertThat(orderService.escalateIfTimeout(plan.orderNo())).isFalse();
80	        clock.advanceMinutes(1);
81	        assertThat(orderService.escalateIfTimeout(plan.orderNo())).isTrue();
82	        // 已升级后重复巡检幂等：不重复升级
83	        assertThat(orderService.escalateIfTimeout(plan.orderNo())).isFalse();
84	        OrderView view = orderService.get(plan.orderNo());
85	        assertThat(view.status()).isEqualTo("ESCALATED");
86	
87	        // 升级态需补签收后执行
88	        flow.sign(plan.orderNo(), "值班领导代签");
89	        flow.execute(plan.orderNo(), "值班员丙");
90	        flow.receipt(plan.orderNo(), "rc-timeout", "值班员丙",
91	                FlowSupport.safeBoundaryOpenings(), null);
92	        assertThat(orderService.get(plan.orderNo()).status()).isEqualTo("RECEIPTED");
93	    }
94	
95	    @Test
96	    @DisplayName("未签收直接执行：拒绝")
97	    void executeWithoutSignRejected() {
98	        PlanView plan = issuedPlan();
99	        assertThatThrownBy(() -> flow.execute(plan.orderNo(), "值班员甲"))
100	                .isInstanceOf(FloodControlException.class)
101	                .hasMessageContaining("需先签收");
102	    }
103	
104	    @Test
105	    @DisplayName("回执偏差恰 10%（实际 22 vs 方案 20）：视为一致，无需原因")
106	    void receiptDeviationExactlyTenPercentOk() {
107	        PlanView plan = issuedPlan();
108	        flow.sign(plan.orderNo(), "值班员甲");
109	        flow.execute(plan.orderNo(), "值班员甲");
