14	    /**
15	     * 判断方案总泄量是否合法：不得超过下游安全泄量，恰等合法。
16	     */
17	    public static boolean withinSafeLimit(BigDecimal totalRelease, BigDecimal safeRelease) {
18	        return totalRelease.compareTo(safeRelease) <= 0;
19	    }
