22	     * 回执偏差比例 = |实际总泄量 - 方案总泄量| / 方案总泄量，保留 6 位小数（截断后比较仍以精确值为准）。
23	     *
24	     * @return 非负偏差比例
25	     */
26	    public static BigDecimal deviationRatio(BigDecimal actual, BigDecimal planned) {
27	        if (planned.compareTo(BigDecimal.ZERO) == 0) {
28	            return actual.compareTo(BigDecimal.ZERO) == 0
29	                    ? BigDecimal.ZERO
30	                    : BigDecimal.ONE;
31	        }
32	        return actual.subtract(planned).abs()
33	                .divide(planned, 6, RoundingMode.HALF_UP);
34	    }
35	
36	    /**
37	     * 偏差是否一致：偏差比例恰等允许比例（默认 10%）视为一致，超过则须附原因。
38	     *
39	     * @param ratio 偏差比例
40	     * @param allowed 允许比例（含边界）
41	     */
42	    public static boolean deviationConsistent(BigDecimal ratio, double allowed) {
43	        return ratio.compareTo(BigDecimal.valueOf(allowed)) <= 0;
44	    }
45	}
