19	
20	/**
21	 * 泄流方案 H2 集成测试：泄量恰等安全值合法、超限拒绝、同库执行中唯一、幂等重放。
22	 */
23	class PlanIntegrationTest extends AbstractIntegrationTest {
24	
25	    @Autowired
26	    private PlanService planService;
27	    @Autowired
28	    private PlanRepository planRepository;
29	    @Autowired
30	    private FlowSupport flow;
31	
32	    private RoutingView releaseRequiredRouting(String warningReq, String routingReq,
33	                                               String warningNo) {
34	        return flow.route(routingReq, warningNo, new BigDecimal("200.0000"),
35	                new BigDecimal("400001"), new BigDecimal("150"), new BigDecimal("10"));
36	    }
37	
38	    @Test
39	    @DisplayName("总泄量恰等于下游安全泄量 20 m3/s：合法生效并下达指令")
40	    void totalReleaseExactlySafeLimitAllowed() {
41	        WarningView warning = flow.openWarning("w-plan-safe");
42	        RoutingView routing = releaseRequiredRouting("w-plan-safe", "r-plan-safe",
43	                warning.warningNo());
44	        PlanView plan = flow.createPlan("p-plan-safe", warning.warningNo(),
45	                routing.routingNo(), FlowSupport.safeBoundaryOpenings());
46	        assertThat(plan.totalRelease()).isEqualByComparingTo("20.000");
47	        assertThat(plan.downstreamSafeRelease()).isEqualByComparingTo("20.000");
48	        assertThat(plan.status()).isEqualTo("EFFECTIVE");
49	        assertThat(plan.orderNo()).isNotNull();
50	        assertThat(plan.orderStatus()).isEqualTo("ISSUED");
51	        assertThat(plan.replay()).isFalse();
52	    }
53	
54	    @Test
