56	    void totalReleaseExceedsSafeLimitRejected() {
57	        WarningView warning = flow.openWarning("w-plan-over");
58	        RoutingView routing = flow.route("r-plan-over", warning.warningNo(),
59	                new BigDecimal("200.0000"), new BigDecimal("400001"),
60	                new BigDecimal("150"), new BigDecimal("10"));
61	        List<OpeningItem> over = List.of(
62	                new OpeningItem("1#闸门", new BigDecimal("1.0"), new BigDecimal("15.000")),
63	                new OpeningItem("2#闸门", new BigDecimal("1.0"), new BigDecimal("5.001")));
64	        assertThatThrownBy(() -> flow.createPlan("p-plan-over", warning.warningNo(),
65	                routing.routingNo(), over))
66	                .isInstanceOf(FloodControlException.class)
67	                .hasMessageContaining("超过下游安全泄量");
68	        Integer planCount = jdbcTemplate.queryForObject(
69	                "SELECT COUNT(1) FROM release_plan", Integer.class);
70	        assertThat(planCount).isZero();
71	    }
