75	    void planRejectedWhenNotRequired() {
76	        WarningView warning = flow.openWarning("w-plan-not-needed");
77	        RoutingView routing = flow.route("r-plan-not-needed", warning.warningNo(),
78	                new BigDecimal("200.0000"), new BigDecimal("300000"),
79	                new BigDecimal("150"), new BigDecimal("10"));
80	        assertThat(routing.dangerJudgment()).isEqualTo("SAFE");
81	        assertThatThrownBy(() -> flow.createPlan("p-plan-not-needed", warning.warningNo(),
82	                routing.routingNo(), FlowSupport.safeBoundaryOpenings()))
83	                .isInstanceOf(FloodControlException.class)
84	                .hasMessageContaining("无需制定泄流方案");
85	    }
