87	    @Test
88	    @DisplayName("同一尾矿库同时刻只允许一个执行中方案；回执闭环后可再制定")
89	    void onlyOneEffectivePlanPerPond() {
90	        WarningView warning = flow.openWarning("w-plan-unique");
91	        RoutingView routing = flow.route("r-plan-unique", warning.warningNo(),
92	                new BigDecimal("200.0000"), new BigDecimal("400001"),
93	                new BigDecimal("150"), new BigDecimal("10"));
