95	                routing.routingNo(), FlowSupport.safeBoundaryOpenings());
96	
97	        // 同一处置链下第二个执行中方案必须被唯一约束拒绝
98	        assertThatThrownBy(() -> flow.createPlan("p-plan-unique-2", warning.warningNo(),
99	                routing.routingNo(), List.of(new OpeningItem("备用孔口",
100	                        new BigDecimal("0.5"), new BigDecimal("5.000")))))
101	                .isInstanceOf(FloodControlException.class)
102	                .hasMessageContaining("执行中的泄流方案");
103	
104	        // 回执闭环解除执行中位
105	        flow.sign(first.orderNo(), "值班员甲");
106	        flow.execute(first.orderNo(), "值班员甲");
107	        flow.receipt(first.orderNo(), "rc-plan-unique", "值班员甲",
