package com.example.starter.flood.domain;

/**
 * 滚动演算泄流能力判定：当前方案泄流能力对比入库洪水过程线剩余段峰值需求。
 */
public enum ReleaseJudgment {
    /** 泄流能力大于需求：充足。 */
    SUFFICIENT,
    /** 泄流能力恰等于需求：临界（不判不足，不触发提级）。 */
    CRITICAL,
    /** 泄流能力小于需求：不足，须提升预警级别并追加泄流方案版本。 */
    INSUFFICIENT
}

package com.example.starter.flood.domain;

/**
 * 预警级别：BLUE &lt; YELLOW &lt; ORANGE &lt; RED。
 * 滚动演算判定泄流能力不足时自动逐级提升；已为 RED 时保持并留痕。
 */
public enum WarningLevel {
    /** 蓝色（最低）。 */
    BLUE,
    /** 黄色。 */
    YELLOW,
    /** 橙色（合成数据默认级别）。 */
    ORANGE,
    /** 红色（最高，不可再升）。 */
    RED;

    /**
     * 提升一级；已为最高级时返回自身。
     */
    public WarningLevel escalate() {
        return switch (this) {
            case BLUE -> YELLOW;
            case YELLOW -> ORANGE;
            case ORANGE -> RED;
            case RED -> RED;
        };
    }
}

package com.example.starter.flood.domain;

/**
 * 在途指令冲突替代建议的人工确认决策。
 */
public enum SuggestionDecision {
    /** 采纳新版本：按新方案版本另行下达指令（在途指令仍按原版本执行至闭环）。 */
    ADOPT_NEW_VERSION,
    /** 维持原版本：在途指令继续按创建时的方案版本执行。 */
    KEEP_ORIGINAL_VERSION
}

