                ps.setString(12, po.confirmNote);
                ps.setString(13, po.confirmRequestId);
                ps.setTimestamp(14, Timestamp.valueOf(po.createdAt));
                return ps;
            }, keyHolder);
            Number key = keyHolder.getKey();
            if (key != null) {
                po.id = key.longValue();
            }
        } catch (DuplicateKeyException e) {
