import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 入库洪水过程线点。
 *
 * @param forecastTime 预报时刻（时区 Asia/Shanghai）
 * @param inflowRate 该时刻入库流量，立方米每秒
 */
public record HydrographPointItem(
        @NotNull LocalDateTime forecastTime,
        @NotNull @DecimalMin("0.0") BigDecimal inflowRate) {
}

package com.example.starter.flood.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.util.List;

/**
 * 入库洪水过程线录入请求；同一处置链内按预报时刻归位，同时刻后报覆盖先报。
 *
 * @param requestId 幂等键
 * @param points 过程线点（预报时刻 + 入库流量）
 */
public record HydrographRequest(
        @NotBlank String requestId,
        @NotEmpty @Valid List<HydrographPointItem> points) {
}

package com.example.starter.flood.web.dto;

/**
 * 入库洪水过程线录入结果视图。
 *
 * @param warningNo 处置链预警编号
 * @param acceptedPoints 本次受理点数
 * @param totalPoints 该处置链过程线总点数
 * @param replay 是否幂等重放（同 requestId 同参重放返回首次结果）
 */
public record HydrographView(
        String warningNo,
        int acceptedPoints,
        int totalPoints,
        boolean replay) {
}

